883: void display_manager_tick(velawear_display_t *display)
884: {
885:   uint32_t now;
886:   velawear_state_t state;
887:   lv_obj_t *alert_label;
888: 
889:   if (display == NULL || !display->initialized)
890:     {
891:       return;
892:     }
893: 
894:   now = display_now_ms();
895:   display_audio_poll(display);
896:   pthread_mutex_lock(&display->lock);
897:   if (display->alert_pending)
898:     {
899:       lv_obj_set_style_bg_color(lv_screen_active(), lv_color_hex(0x5b1111), 0);
900:       lv_label_set_text(display->status_label, "主动提醒");
901:       lv_obj_set_style_text_color(display->status_label,
902:                                   lv_color_hex(0xfca5a5), 0);
903:       alert_label = display->detail_active ? display->metrics_label :
904:                     display->page_content[0];
905:       if (alert_label != NULL)
906:         {
907:           lv_label_set_text(alert_label, display->pending_alert);
908:           lv_obj_set_style_text_color(alert_label,
909:                                       lv_color_hex(UI_TEXT_COLOR), 0);
910:         }
911:       if (g_alert_message != NULL && g_alert_overlay != NULL)
912:         {
913:           lv_label_set_text(g_alert_message, display->pending_alert);
914:           lv_obj_clear_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
915:           lv_obj_move_foreground(g_alert_overlay);
916:         }
917:       display->alert_until_ms = now + 60000;
918:       display->alert_active = true;
919:       syslog(LOG_INFO,
920:              "[Display] Alert consumed page=%u detail=%d label=%p hold=60000ms text=%s\n",
921:              (unsigned int)display->page_index, display->detail_active ? 1 : 0,
922:              alert_label, display->pending_alert);
923:       display->alert_pending = false;
924:     }
925:   pthread_mutex_unlock(&display->lock);
926: 
927:   if (display->alert_active)
928:     {
929:       if (now < display->alert_until_ms)
930:         {
931:           lv_timer_handler();
932:           return;
933:         }
934: 
935:       display->alert_active = false;
936:       syslog(LOG_INFO, "[Display] Alert expired\n");
937:       if (g_alert_overlay != NULL)
938:         {
939:           lv_obj_add_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
940:         }
941:       display_restore_theme(display);
942:       display->last_update_ms = 0;
943:     }
944: 
945:   if (display->last_update_ms == 0 || now - display->last_update_ms >=
946:       (display->active_app == VELAWEAR_APP_STOPWATCH &&
947:        display->stopwatch_running ? 100 : 250))
948:     {
949:       state = state_manager_get_state(display->state_mgr);
950:       if (display->detail_active)
951:         {
952:           display_render_app(display, &state);
953:         }
954:       else
955:         {
956:           display_render_top(display, &state);
957:         }
958:       display->last_update_ms = now;
959:     }
960: 
961:   lv_timer_handler();
962: }
