static void *velawear_ble_init_thread(void *context)
{
  velawear_agent_t *agent = (velawear_agent_t *)context;
  int ret;

  if (agent == NULL)
    {
      return NULL;
    }

  agent->ble_init_state = VELAWEAR_BLE_INIT_RUNNING;
  syslog(LOG_INFO, "[BLE] async init worker started\n");

  ret = velawear_ble_init(&agent->config, &agent->events);
  if (ret < 0)
    {
      agent->ble_available = false;
      agent->ble_init_state = VELAWEAR_BLE_INIT_FAILED;
      syslog(LOG_WARNING, "[VelaWear] BLE init failed: %d\n", ret);
      return NULL;
    }

  agent->ble_available = true;
  syslog(LOG_INFO, "[BLE] init result=%d available=1\n", ret);

#ifdef CONFIG_VELAWEAR_XIAOZHI_PAN
  /*
   * Keep the existing controller settle interval and initialization order.
   * This worker is deliberately the only caller of BLE/PAN startup.
   */
  usleep(500000);
  ret = velawear_pan_init(&agent->events);
  if (ret < 0)
    {
      agent->ble_init_state = VELAWEAR_BLE_INIT_FAILED;
      syslog(LOG_WARNING, "[VelaWear] PAN init failed: %d\n", ret);
      return NULL;
    }
  agent->pan_init_succeeded = true;
#endif

  agent->ble_init_state = VELAWEAR_BLE_INIT_READY;
  syslog(LOG_INFO, "[BLE] async init ready available=%d pan=%d\n",
         agent->ble_available ? 1 : 0,
         agent->pan_init_succeeded ? 1 : 0);
  return NULL;
}

static void velawear_start_ble_init(velawear_agent_t *agent)
{
  int ret;

  agent->ble_init_state = VELAWEAR_BLE_INIT_NOT_STARTED;
#if VELAWEAR_ENABLE_BLE
  /*
   * Use pthread_create(NULL) so the platform default pthread stack is used;
   * the BLE/PAN worker must not add another oversized static stack.
   */
  agent->ble_init_state = VELAWEAR_BLE_INIT_RUNNING;
  ret = pthread_create(&agent->ble_init_thread, NULL,
                       velawear_ble_init_thread, agent);
  if (ret != 0)
    {
      agent->ble_init_state = VELAWEAR_BLE_INIT_FAILED;
      syslog(LOG_WARNING,
             "[BLE] async init worker create failed: %d; continuing without BLE\n",
             ret);
      return;
    }

  agent->ble_init_thread_started = true;
  syslog(LOG_INFO, "[BLE] async init worker requested\n");
#else
  syslog(LOG_INFO, "[BLE] deferred; core MVP mode\n");
#endif
}

static bool velawear_stop_ble_init(velawear_agent_t *agent)
{
  int ret;
  int state = agent->ble_init_state;

  if (!agent->ble_init_thread_started)
    {
      return true;
    }

  /*
   * BLE/HCI can be controller-bound.  Never make teardown wait forever for
   * an initialization call that did not return.
   */
  for (int i = 0; i < 20 && state == VELAWEAR_BLE_INIT_RUNNING; i++)
    {
      usleep(50000);
      state = agent->ble_init_state;
    }

  if (state == VELAWEAR_BLE_INIT_RUNNING)
    {
      syslog(LOG_WARNING,
             "[BLE] async init still running; skip BLE/PAN cleanup\n");
      return false;
    }

  ret = pthread_join(agent->ble_init_thread, NULL);
  if (ret != 0)
    {
      syslog(LOG_WARNING,
             "[BLE] async init worker join failed: %d; skip BLE/PAN cleanup\n",
             ret);
      return false;
    }

  agent->ble_init_thread_started = false;
  return true;
}

static int velawear_init(velawear_agent_t *agent)
{
  int ret;

  /* Initialize configuration */

  ret = velawear_config_init(&agent->config);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[VelaWear] Config init failed: %d\n", ret);
      return ret;
    }

