   */
  agent->ble_init_state = VELAWEAR_BLE_INIT_NOT_STARTED;
#if VELAWEAR_ENABLE_BLE
  ret = VELAWEAR_OK;
  syslog(LOG_INFO,
         "[BLE] init deferred to background worker; Agent startup continues\n");
