  if (ret < 0)
    {
      syslog(LOG_ERR, "[VelaWear] Action manager init failed: %d\n", ret);
      return ret;
    }

  ret = action_manager_set_receipt_callback(&agent->actions,
                                             velawear_action_receipt_callback,
                                             agent);
  if (ret < 0)
    {

  display->page_title = lv_label_create(screen);
  display_apply_font(display->page_title);
  lv_label_set_text(display->page_title, "黄山派");
